/**
 * Provenance stamping for generated artifacts
 *
 * All artifacts generated by the platform CLI are stamped with
 * provenance metadata for auditing and traceability.
 */

import { createHash, randomUUID } from 'crypto';
import { readFile } from 'fs/promises';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import type { ExecutionContext } from '../types/context.js';
import type { ProvenanceStamp, AuditEvent, ArtifactMetadata } from '../types/provenance.js';

const __dirname = dirname(fileURLToPath(import.meta.url));

/**
 * Get CLI version from package.json
 */
async function getCliVersion(): Promise<string> {
  try {
    const packagePath = join(__dirname, '..', '..', 'package.json');
    const content = await readFile(packagePath, 'utf-8');
    const pkg = JSON.parse(content) as { version?: string };
    return pkg.version ?? '0.0.0';
  } catch {
    return '0.0.0';
  }
}

/**
 * Compute content hash for artifact
 */
export function computeContentHash(content: string): string {
  return createHash('sha256').update(content).digest('hex');
}

/**
 * Generate a provenance stamp for an artifact
 */
export async function generateProvenanceStamp(
  content: string,
  context: ExecutionContext
): Promise<ProvenanceStamp> {
  const cliVersion = await getCliVersion();

  return {
    stampId: randomUUID(),
    cliVersion,
    generatedAt: new Date().toISOString(),
    correlationId: context.correlationId,
    orgId: context.org.orgId,
    envId: context.env.envId,
    contentHash: computeContentHash(content),
  };
}

/**
 * Create an audit event for a CLI operation
 */
export function createAuditEvent(
  command: string,
  args: string[],
  context: ExecutionContext,
  outcome: 'success' | 'failure' | 'dry-run',
  durationMs: number,
  errorMessage?: string
): AuditEvent {
  return {
    eventId: randomUUID(),
    timestamp: new Date().toISOString(),
    correlationId: context.correlationId,
    command,
    args,
    orgId: context.org.orgId,
    envId: context.env.envId,
    outcome,
    durationMs,
    errorMessage,
  };
}

/**
 * Create artifact metadata with provenance
 */
export async function createArtifactMetadata(
  artifactId: string,
  artifactType: 'plan' | 'config' | 'manifest' | 'export',
  content: string,
  context: ExecutionContext,
  sourceFiles?: string[],
  dependencies?: string[]
): Promise<ArtifactMetadata> {
  const provenance = await generateProvenanceStamp(content, context);

  return {
    artifactId,
    artifactType,
    createdAt: new Date().toISOString(),
    provenance,
    sourceFiles,
    dependencies,
  };
}

/**
 * Format provenance stamp as JSON for embedding in artifacts
 */
export function formatProvenanceAsJson(stamp: ProvenanceStamp): string {
  return JSON.stringify({
    _provenance: {
      version: '1.0',
      ...stamp,
    },
  }, null, 2);
}

/**
 * Format provenance stamp as comment for embedding in code
 */
export function formatProvenanceAsComment(stamp: ProvenanceStamp, commentStyle: '//' | '#' | '--'): string {
  const lines = [
    `${commentStyle} PROVENANCE STAMP`,
    `${commentStyle} Generated by: agentics-platform-cli v${stamp.cliVersion}`,
    `${commentStyle} Timestamp: ${stamp.generatedAt}`,
    `${commentStyle} Correlation ID: ${stamp.correlationId}`,
    `${commentStyle} Organization: ${stamp.orgId}`,
    `${commentStyle} Environment: ${stamp.envId}`,
    `${commentStyle} Content Hash: ${stamp.contentHash}`,
    `${commentStyle} Stamp ID: ${stamp.stampId}`,
  ];

  return lines.join('\n');
}

/**
 * Verify a provenance stamp against content
 */
export function verifyProvenanceStamp(content: string, stamp: ProvenanceStamp): boolean {
  const actualHash = computeContentHash(content);
  return actualHash === stamp.contentHash;
}
